-- Rename the summary-history column and enum to say what they hold.
--
-- `ai_generated` described the producer ("a model wrote this") which is true of
-- almost every row and therefore carries no information. `briefing_generated` names
-- the distinction the application actually branches on: a row generated by the model
-- versus one carried over from the previous snapshot.
--
-- Renames preserve every existing row. Dropping and re-adding the column would reset
-- all of them to the default, silently losing which summaries were model-generated.

ALTER TABLE assistant_summary_histories
  RENAME COLUMN ai_generated TO briefing_generated;

-- Prisma stores enums as PostgreSQL enum types; the type and its values move together.
ALTER TYPE "AiSummaryHistoryKind" RENAME TO "DigestHistoryKind";